CREATE TYPE "calendar_event_type" AS ENUM ('ORIENTATION','SEMINAR','MEETING','TRAINING','COMPANY_ACTIVITY','OTHER');
CREATE TYPE "calendar_event_status" AS ENUM ('ACTIVE','CANCELLED');
CREATE TYPE "holiday_type" AS ENUM ('REGULAR','SPECIAL_NON_WORKING','SPECIAL_WORKING','LOCAL');
CREATE TYPE "holiday_scope" AS ENUM ('NATIONAL','LOCAL','COMPANY');
CREATE TABLE "calendar_events" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"created_by_id" UUID NOT NULL,"company_id" UUID,"school_id" UUID,"title" VARCHAR(255) NOT NULL,"description" TEXT,"event_date" DATE NOT NULL,"start_time" TIME(0),"end_time" TIME(0),"location" VARCHAR(255),"audience" "announcement_audience" NOT NULL DEFAULT 'ALL_USERS',"event_type" "calendar_event_type" NOT NULL DEFAULT 'OTHER',"status" "calendar_event_status" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "calendar_events_pkey" PRIMARY KEY ("id"));
CREATE TABLE "holidays" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"created_by_id" UUID NOT NULL,"company_id" UUID,"holiday_date" DATE NOT NULL,"name" VARCHAR(255) NOT NULL,"holiday_type" "holiday_type" NOT NULL,"scope" "holiday_scope" NOT NULL DEFAULT 'NATIONAL',"locality" VARCHAR(255),"source_reference" TEXT,"is_active" BOOLEAN NOT NULL DEFAULT true,"is_manual" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "holidays_pkey" PRIMARY KEY ("id"));
CREATE INDEX "calendar_events_date_status_idx" ON "calendar_events"("event_date","status"); CREATE INDEX "calendar_events_company_idx" ON "calendar_events"("company_id"); CREATE INDEX "calendar_events_school_idx" ON "calendar_events"("school_id"); CREATE INDEX "calendar_events_audience_idx" ON "calendar_events"("audience");
CREATE UNIQUE INDEX "holidays_date_name_scope_company_key" ON "holidays"("holiday_date","name","scope","company_id"); CREATE INDEX "holidays_date_active_idx" ON "holidays"("holiday_date","is_active"); CREATE INDEX "holidays_company_idx" ON "holidays"("company_id");
ALTER TABLE "calendar_events" ADD CONSTRAINT "calendar_events_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT; ALTER TABLE "calendar_events" ADD CONSTRAINT "calendar_events_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE RESTRICT; ALTER TABLE "calendar_events" ADD CONSTRAINT "calendar_events_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT;
ALTER TABLE "holidays" ADD CONSTRAINT "holidays_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT; ALTER TABLE "holidays" ADD CONSTRAINT "holidays_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE RESTRICT;
ALTER TABLE "calendar_events" ADD CONSTRAINT "calendar_events_time_order" CHECK ("end_time" IS NULL OR "start_time" IS NULL OR "end_time">"start_time");
